import {FEATURES} from './community-features.js';
import {esc,parseRadar} from './weather-tools.js';
import {CITIES,normalizeCity} from './places.js';
import {distanceKm,distanceText,rankShelters,directionsURL,rainWindow,radarPixel,scanRadarTiles} from './nearby-tools.js';
const $=s=>document.querySelector(s);
export function createNearby(ctx){
 let key='',data=null,error='',busy=false,sequence=0,radar=null,radarBusy=false,radarError='',radarKey='',radarLoadedAt=0,radarSeq=0,kind='all',hazard='pioggia',map=null,mapSeq=0;
 const placeKey=()=>ctx.get().place.latitude+','+ctx.get().place.longitude;
 function sync(){if(key!==placeKey()){key=placeKey();sequence++;busy=false;data=null;error='';radar=null;radarKey='';radarSeq++;radarBusy=false;radarError=''}}
 const list=()=>rankShelters(data?.places||[],ctx.get().place,kind);
 function locationStrip(){const p=ctx.get().place;return `<div class="near-location"><div><b>⌖ ${esc(p.name)}</b><small>${p.source==='gps'?'Posizione del dispositivo · rilevazione singola':'Distanze dal punto selezionato, non dal dispositivo'}</small></div><button data-near-gps>Usa la mia posizione</button></div>`}
 function proximity(){const {weather}=ctx.get(),next=rainWindow(weather);return `<div class="proximity-grid"><article><span>${hazard==='grandine'?'Grandine segnalata':'Precipitazioni sul radar'}</span><div id="near-radar-result">${radarResult()}</div><button data-near-radar ${radarBusy?'disabled':''}>${radarBusy?'Lettura del radar…':'Aggiorna distanza'}</button></article><article><span>${hazard==='grandine'?'Tempo di arrivo della grandine':'Prossima ora con pioggia prevista'}</span><strong>${hazard==='grandine'?'Non disponibile':next?next.time.slice(11,16):'Non individuata'}</strong><p>${hazard==='grandine'?'Serve un servizio che segua lo spostamento delle celle. La distanza di un post non permette di calcolare l’arrivo.':next?`${new Date(next.time.slice(0,10)+'T12:00:00').toLocaleDateString('it-IT',{day:'numeric',month:'short'})} · ${next.probability}% · ${next.mm} mm. Intervallo orario del modello Open-Meteo, non un conto alla rovescia.`:'Nelle prossime 12 ore non risulta un intervallo con almeno 40% e 0,1 mm, oppure mancano dati. Non esclude pioggia locale.'}</p></article></div>`}
 function radarResult(){if(radarError)return `<p role="status">${esc(radarError)}</p>`;if(!radar)return '<strong>— km</strong><p>Consulta il radar recente o le segnalazioni disponibili.</p>';if(hazard==='grandine')return `<strong>${radar.nearest?'≈ '+distanceText(radar.nearest.distance):'Nessun post vicino'}</strong><p>${radar.nearest?`Dal centro di ${esc(radar.nearest.city)}, località indicata nel post. Non è la distanza dalla grandine. Ultimo post: ${new Date(radar.nearest.created).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}.`:'Nessuna segnalazione delle ultime 2 ore associabile alle città conosciute entro 100 km. Copertura della community incompleta.'}</p>`;return `<strong>${radar.result.nearest?'≈ '+distanceText(radar.result.nearest.km):'Non rilevate entro 50 km'}</strong><p>Echi radar colorati, anche neve. ${radar.result.coverage<.98?'Copertura parziale: '+Math.round(radar.result.coverage*100)+'% dell’area. ':''}Immagine delle ${new Date(radar.time*1000).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}. Risoluzione circa ${radar.result.resolutionKm.toFixed(1)} km; la distanza non indica direzione o tempo di arrivo.</p><small>RainViewer · livello di riflettività da 15 dBZ. I singoli radar possono avere orari diversi.</small>`}
 function results(compact=false){const places=list(),shown=compact?places.slice(0,3):places;return `${error?`<p role="alert">${esc(error)}</p>`:''}${!data&&error?'<button data-near-refresh>Riprova la ricerca</button>':!data?`<p role="status">${busy?'Cerco luoghi coperti entro 5 km…':'Caricamento dei luoghi…'}</p>`:shown.length?`<div class="near-place-list">${shown.map((p,i)=>`<article class="near-place"><span class="near-number">${i+1}</span><div><span class="near-type">${p.type==='car'?'PARCHEGGIO COPERTO':p.type==='people'?'EDIFICIO PUBBLICO':'LUOGO DELLA COMMUNITY'} · ${esc(p.source)}</span><h3>${esc(p.name)}</h3><p>${esc(p.details||'Indirizzo non indicato')}</p><small>${p.openingHours?'Orari indicati: '+esc(p.openingHours):'Apertura da verificare'} · ${esc(p.fee)}</small><div class="near-actions"><a class="button" href="${esc(directionsURL(p,p.type==='people'?'people':'car'))}" target="_blank" rel="noopener">Indicazioni ${p.type==='people'?'a piedi':'in auto'} ↗</a><button data-near-pin="${esc(p.id)}">Sulla mappa</button>${p.sourceURL?`<a href="${esc(p.sourceURL)}" target="_blank" rel="noopener">Scheda OSM ↗</a>`:`<button data-near-report="${esc(p.id)}">Segnala un problema</button>${p.author===ctx.get().me?.id?`<button data-near-delete="${esc(p.id)}">Elimina</button>`:''}`}</div></div><b class="near-distance">${distanceText(p.distance)}</b></article>`).join('')}</div>`:`<div class="near-empty"><h3>${data?.sourceError?'Ricerca cartografica incompleta':'Nessun luogo corrispondente entro 5 km'}</h3><p>${data?.sourceError?'La fonte dei luoghi non è disponibile. Riprova o apri la ricerca su Google Maps.':'Cambia filtro o esplora un’altra località. La mappa può essere incompleta.'}</p><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent((kind==='people'?'biblioteca ':'parcheggio coperto ')+ctx.get().place.latitude+','+ctx.get().place.longitude)}" target="_blank" rel="noopener">Cerca anche su Google Maps ↗</a></div>`}${data?.osmAt?`<p class="near-footnote">Cartografia OSM del ${new Date(data.osmAt).toLocaleDateString('it-IT')}. La data non conferma apertura o accessibilità.</p>`:''}${data?.sourceError?`<p class="near-notice" role="status">${esc(data.sourceError)}</p>`:''}<p class="near-footnote">Distanze in linea d’aria dal punto selezionato. Orari, accessibilità, copertura e posti liberi da verificare. Gli edifici pubblici possono essere chiusi; i parcheggi sotterranei non sono indicati in caso di allagamenti.</p>`}
 function panel(layer){if(!FEATURES.coveredPlaces)return ''; const next=layer==='grandine'?'grandine':'pioggia';if(next!==hazard){radarSeq++;radarBusy=false;radar=null;radarError='';radarKey=''}hazard=next;sync();return `<section class="nearby-panel" id="nearby-panel"><div class="near-heading"><div><span class="eyebrow">METEO → DISTANZA → LUOGHI</span><h2>${hazard==='grandine'?'Grandine: cosa sappiamo vicino a te':'Pioggia: quanto è vicina?'}</h2></div><a href="#ripari">Tutti i luoghi coperti →</a></div>${locationStrip()}${proximity()}<h3>Dove cercare copertura · entro 5 km</h3><div id="nearby-results">${results(true)}</div></section>`}
 function page(){sync();return `<section class="nearby-workspace"><div class="atlas-title"><div><h1>Trova un luogo coperto.</h1><p>La zona scelta, le distanze e un percorso da aprire.</p></div><a href="#guida" class="guide-link">? Guida</a></div>${locationStrip()}<div class="near-hazard-tabs">${[['pioggia','Pioggia'],['grandine','Grandine']].map(([id,label])=>`<button data-near-hazard="${id}" aria-pressed="${hazard===id}">${label}</button>`).join('')}<a href="#mappa">Cambia località</a></div>${proximity()}<div class="nearby-map" id="nearby-map" role="region" aria-label="Mappa dei luoghi coperti vicini"></div><div class="near-filters"><div>${[['all','Tutti'],['car','Per l’auto'],['people','A piedi']].map(([id,label])=>`<button data-near-kind="${id}" aria-pressed="${kind===id}">${label}</button>`).join('')}</div><button data-near-refresh>Aggiorna luoghi</button></div><div id="nearby-results">${results()}</div><div class="near-footer"><button data-near-add>＋ Aggiungi un luogo pubblico</button><a href="#offline">Luoghi salvati offline</a><button data-near-ai>✦ Spiegami questi dati</button></div><p class="near-footnote">Cartografia: © OpenStreetMap contributors, ODbL · servizio Overpass Private.coffee. La ricerca esterna usa coordinate arrotondate a circa 1 km. Non ci sono prenotazioni o disponibilità in tempo reale.</p></section>`}
 async function load(force=false){sync();if(busy||(!force&&(data||error)))return;busy=true;error='';const token=++sequence,p=ctx.get().place;refreshResults();try{const d=await ctx.api('pulse/nearby?'+new URLSearchParams({lat:p.latitude.toFixed(2),lon:p.longitude.toFixed(2),category:kind==='people'?'people':'car'}));if(token===sequence)data=d}catch(e){if(token===sequence)error=e.message}finally{if(token===sequence){busy=false;refreshResults();if($('#nearby-map'))mountMap()}}}
 function refreshResults(){const el=$('#nearby-results');if(el){el.innerHTML=results(!$('#nearby-map'));bindResults()}}
 function imageData(url){return new Promise((resolve,reject)=>{const i=new Image(),timer=setTimeout(()=>{i.src='';reject(Error('Le immagini radar non rispondono. Riprova.'))},12000);i.crossOrigin='anonymous';i.onload=()=>{clearTimeout(timer);try{const c=document.createElement('canvas');c.width=256;c.height=256;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(i,0,0,256,256);resolve(x.getImageData(0,0,256,256))}catch{reject(Error('Questo browser non consente la lettura del radar. Apri il livello Radar.'))}};i.onerror=()=>{clearTimeout(timer);reject(Error('Immagine radar non disponibile.'))};i.src=url})}
 async function readRadar(force=false){sync();const k=key+'|'+hazard;if(radarBusy||(!force&&radarKey===k&&radar&&Date.now()-radarLoadedAt<300000))return;radarBusy=true;radarError='';radar=null;radarKey=k;const token=++radarSeq,p={...ctx.get().place},h=hazard;refreshProximity();try{let result;if(h==='grandine'){const d=await ctx.api('atlas/reports'),reports=d.posts.filter(r=>r.kind==='Grandine'&&r.created>Date.now()-7200000&&r.created<=Date.now()&&(!r.expires||r.expires>Date.now())).flatMap(r=>{const c=CITIES.find(c=>normalizeCity(c.name)===normalizeCity(r.city));return c?[{...r,distance:distanceKm(p,c)}]:[]}).filter(r=>r.distance<=100).sort((a,b)=>a.distance-b.distance);result={nearest:reports[0]||null,time:Date.now()/1000}}else{
  if(Math.abs(p.latitude)>75)throw Error('Analisi della distanza radar disponibile tra 75° sud e 75° nord.');
  const r=await fetch('https://api.rainviewer.com/public/weather-maps.json',{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('Fonte radar non disponibile.');const d=parseRadar(await r.json()),f=d.frames.at(-1),pixel=radarPixel(p),pxRadius=55/(40075*Math.cos(p.latitude*Math.PI/180)/(256*128));const tiles=[];
  for(let x=Math.floor((pixel.x-pxRadius)/256);x<=Math.floor((pixel.x+pxRadius)/256);x++)for(let y=Math.max(0,Math.floor((pixel.y-pxRadius)/256));y<=Math.min(127,Math.floor((pixel.y+pxRadius)/256));y++)tiles.push({x,y});if(tiles.length>9)throw Error('Area radar troppo estesa a questa latitudine. Usa il livello Radar.');
  const images=await Promise.all(tiles.map(async t=>{const suffix='/256/7/'+((t.x%128+128)%128)+'/'+t.y;const [a,b]=await Promise.all([imageData(d.host+f.path+suffix+'/2/0_0.png'),imageData(d.host+'/v2/coverage/0'+suffix+'/0/0_0.png')]);return {...t,radar:a,coverage:b}}));
  const scanned=scanRadarTiles(images,p);if(scanned.coverage<.02)throw Error('Copertura radar insufficiente nella zona. Non è possibile stimare una distanza.');result={result:scanned,time:f.time};
 }if(token===radarSeq&&key===placeKey()&&h===hazard){radar=result;radarLoadedAt=Date.now()}}catch(e){if(token===radarSeq)radarError=e.message}finally{if(token===radarSeq){radarBusy=false;refreshProximity()}}}
 function refreshProximity(){const el=$('.proximity-grid');if(el){el.outerHTML=proximity();document.querySelectorAll('[data-near-radar]').forEach(b=>b.onclick=()=>readRadar(true))}}
 async function mountMap(){const host=$('#nearby-map');if(!host)return;const token=++mapSeq;map?.remove();map=null;const L=await import('./assets/leaflet.js');if(token!==mapSeq||!host.isConnected)return;const p=ctx.get().place;map=L.map(host,{scrollWheelZoom:false}).setView([p.latitude,p.longitude],13);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);L.circleMarker([p.latitude,p.longitude],{radius:8,color:'#fff',weight:3,fillColor:'#1260d9',fillOpacity:1}).bindTooltip('Punto selezionato').addTo(map);for(const [i,s]of list().entries())L.marker([s.latitude,s.longitude],{icon:L.divIcon({className:'near-marker',html:String(i+1),iconSize:[32,32],iconAnchor:[16,16]})}).bindPopup('<b>'+esc(s.name)+'</b><p>'+distanceText(s.distance)+' in linea d’aria</p><a target="_blank" rel="noopener" href="'+esc(directionsURL(s,s.type))+'">Apri indicazioni ↗</a>').addTo(map);L.circle([p.latitude,p.longitude],{radius:5000,color:'#1260d9',weight:1,fillOpacity:.025}).addTo(map)}
 function gps(){if(!navigator.geolocation)return ctx.toast('Posizione non supportata. Cerca una città.');ctx.toast('Richiesta della posizione…');navigator.geolocation.getCurrentPosition(p=>{ctx.choose({name:'La mia zona',latitude:p.coords.latitude,longitude:p.coords.longitude,source:'gps',accuracy:p.coords.accuracy});},()=>ctx.toast('Posizione non disponibile. Puoi usare la città scelta.'),{timeout:12000,maximumAge:60000,enableHighAccuracy:false})}
 function add(){if(!ctx.get().me)return ctx.login();ctx.modal('Aggiungi un luogo pubblico',`<p>Segnala un luogo realmente coperto e aperto al pubblico. Usa le coordinate del luogo, non di casa tua.</p><label class="field">Nome<input id="near-name" required maxlength="100"></label><label class="field">Città<input id="near-city" required maxlength="80" value="${esc(ctx.get().place.source==='gps'?'':ctx.get().place.name)}"></label><div class="compose-fields"><label>Latitudine<input id="near-lat" type="number" min="-90" max="90" step="any" required></label><label>Longitudine<input id="near-lon" type="number" min="-180" max="180" step="any" required></label></div><label class="field">Accesso, copertura e orari<textarea id="near-details" required maxlength="500"></textarea></label><label class="scanner-consent"><input id="near-public" type="checkbox" required> È un luogo pubblico, non un’abitazione privata.</label>`,async()=>{await ctx.api('global/shelter',{name:$('#near-name').value,city:$('#near-city').value,latitude:Number($('#near-lat').value),longitude:Number($('#near-lon').value),details:$('#near-details').value,publicPlace:$('#near-public').checked});data=null;load(true);ctx.toast('Luogo aggiunto alla community. Accesso e copertura restano da verificare.');return true})}
 function bindResults(){document.querySelectorAll('[data-near-refresh]').forEach(b=>b.onclick=()=>load(true));document.querySelectorAll('[data-near-pin]').forEach(b=>b.onclick=()=>{const p=list().find(p=>p.id===b.dataset.nearPin);if(map&&p){map.setView([p.latitude,p.longitude],16);$('#nearby-map').scrollIntoView({behavior:'instant',block:'center'})}else location.hash='ripari'});document.querySelectorAll('[data-near-report]').forEach(b=>b.onclick=()=>{if(!ctx.get().me)return ctx.login();ctx.modal('Segnala un problema','<label class="field">Cosa non va?<input id="near-reason" required maxlength="200"></label>',async()=>{await ctx.api('global/report-shelter',{id:b.dataset.nearReport,reason:$('#near-reason').value});ctx.toast('Segnalazione registrata. La revisione non è immediata.')})});document.querySelectorAll('[data-near-delete]').forEach(b=>b.onclick=()=>ctx.modal('Elimina il tuo luogo','<p>Il luogo non sarà più visibile alla community.</p>',async()=>{await ctx.api('global/delete-shelter',{id:b.dataset.nearDelete});data=null;load(true)}))}
 function bind(){if(!$('#nearby-panel')&&!$('#nearby-map'))return;sync();document.querySelectorAll('[data-near-gps]').forEach(b=>b.onclick=gps);document.querySelectorAll('[data-near-radar]').forEach(b=>b.onclick=()=>readRadar(true));document.querySelectorAll('[data-near-hazard]').forEach(b=>b.onclick=()=>{hazard=b.dataset.nearHazard;radarSeq++;radarBusy=false;radar=null;ctx.render()});document.querySelectorAll('[data-near-kind]').forEach(b=>b.onclick=()=>{if(kind===b.dataset.nearKind)return;kind=b.dataset.nearKind;sequence++;busy=false;document.querySelectorAll('[data-near-kind]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));data=null;load(true)});$('[data-near-refresh]')?.addEventListener('click',()=>load(true));$('[data-near-add]')?.addEventListener('click',add);$('[data-near-ai]')?.addEventListener('click',()=>ctx.askAI('Spiegami distanza radar, previsione oraria e limiti dei luoghi coperti a '+ctx.get().place.name+'. Non dichiarare posti liberi o tempi di arrivo della grandine.'));bindResults();load();readRadar();if($('#nearby-map')&&data)mountMap()}
 return {page,panel,bind,gps,refresh(){if($('#nearby-panel')||$('#nearby-map'))refreshProximity()},dispose(){mapSeq++;map?.remove();map=null}};
}
